/// HID++ long-report vendor collections, as `(usage_page, usage_id, long_only)`.
///
/// Logitech exposes its HID++ long-report (report id `0x11`) under a
/// vendor-defined HID collection, but the page differs by transport:
///
/// - `0xFF00 / 0x0002` — USB, Logi Bolt / Unifying receivers, and
///   Bluetooth-*classic* devices (MX Master over BT).
/// - `0xFF43 / 0x0202` — Bluetooth-*Low-Energy* directly-paired devices
///   (e.g. the Logitech Lift / Signature mice). Same HID++ protocol, just a
///   different vendor page on the BLE HID report descriptor.
/// - `0xFF43 / 0x0602` — wired G-series gaming keyboards (e.g. the G513): a
///   distinct vendor collection on the same `0xFF43` page. Carries both report
///   widths, so it is not long-only.
///
/// `long_only` marks a transport that exposes *only* the long report — no
/// short-report (`0x10`) collection — so short HID++ requests must be
/// up-converted to long (handled by the `hidpp` channel). BLE-direct devices on
/// macOS are long-only; USB / receiver / wired-keyboard devices carry both.
/// Keeping the flag in this table means a new long-only transport is a
/// single-line addition here, with no second site to update.
///
/// Filtering on these pairs gives us one HID node per physical HID++ device on
/// every supported OS, without reading report descriptors (`async-hid 0.4`
/// only exposes those on Linux).
const HIDPP_LONG_COLLECTIONS: [(u16, u16, bool); 3] = [
    (0xff00, 0x0002, false),
    (0xff43, 0x0202, true),
    (0xff43, 0x0602, false),
];

/// Whether `(usage_page, usage_id)` is one of the HID++ long-report collections.
fn is_hidpp_long_collection(usage_page: u16, usage_id: u16) -> bool {
    HIDPP_LONG_COLLECTIONS
        .iter()
        .any(|&(page, usage, _)| (page, usage) == (usage_page, usage_id))
}

/// Whether the matched HID++ collection exposes only the long report, so short
/// requests must be re-framed as long (done in the `hidpp` channel). `false` for
/// pages not in [`HIDPP_LONG_COLLECTIONS`].
// Windows routes short vs long by report id over the composite channel
// (WindowsHidppChannel), so the long-only up-conversion path — and thus this
// helper — is only reached off Windows. Still compiled + unit-tested there.
// Not `expect`: the lint fires in the `--lib` build and not in the `--test`
// one, so an expectation is always unfulfilled for one of them.
#[cfg_attr(
    target_os = "windows",
    expect(clippy::allow_attributes, reason = "see above"),
    allow(
        dead_code,
        reason = "long-only up-conversion is the non-Windows AsyncHidChannel path"
    )
)]
fn is_long_only_collection(usage_page: u16, usage_id: u16) -> bool {
    HIDPP_LONG_COLLECTIONS
        .iter()
        .any(|&(page, usage, long_only)| long_only && (page, usage) == (usage_page, usage_id))
}

pub(crate) async fn enumerate_devices() -> Result<Vec<async_hid::Device>, BackendError> {
    let all: Vec<async_hid::Device> = HID_BACKEND
        .enumerate()
        .await
        .map_err(backend_error)?
        .collect()
        .await;

    // One-time visibility into what the OS actually reports for Logitech nodes,
    // so a transport that uses an unexpected vendor page (e.g. a new BLE mouse)
    // can be diagnosed from `OPENLOGI_LOG=debug` without a rebuild.
    for d in all.iter().filter(|d| d.vendor_id == LOGITECH_VENDOR_ID) {
        debug!(
            name = %d.name,
            pid = format_args!("{:04x}", d.product_id),
            usage_page = format_args!("{:#06x}", d.usage_page),
            usage_id = format_args!("{:#06x}", d.usage_id),
            matched = is_hidpp_long_collection(d.usage_page, d.usage_id),
            "logitech HID node"
        );
    }

    Ok(all)
}

/// Whether an enumerated node belongs to the HID++ channel path.
///
/// Wraps [`is_hidpp_candidate`] with the parts only this backend can answer:
/// the platform node id needed to recognise a `hid-logitech-dj` child node.
pub(crate) fn is_hidpp_node(device: &async_hid::Device) -> bool {
    is_hidpp_candidate(
        device.vendor_id,
        device.product_id,
        device.usage_page,
        device.usage_id,
        is_receiver_child_node(&device.id),
    )
}

/// Whether an enumerated node belongs to the HID++ channel path.
///
/// Standalone drivers have precedence over the generic collection matcher. A
/// Litra Glow intentionally uses the same BLE usage collection as Logitech
/// HID++ peripherals, so the full product/usage tuple must be excluded here;
/// the collection itself remains a valid HID++ candidate for other products.
fn is_hidpp_candidate(
    vendor_id: u16,
    product_id: u16,
    usage_page: u16,
    usage_id: u16,
    receiver_child: bool,
) -> bool {
    vendor_id == LOGITECH_VENDOR_ID
        && is_hidpp_long_collection(usage_page, usage_id)
        && !matches_litra(vendor_id, product_id, usage_page, usage_id)
        && !receiver_child

    async fn refresh(&self) -> Result<Vec<Arc<Device>>, BackendError> {
        self.device_io.ensure_allowed()?;
        let devices: Vec<Arc<Device>> = enumerate_devices()
            .await?
            .into_iter()
            .map(Arc::new)
            .collect();
        self.device_io.ensure_allowed()?;
        let handles = devices
            .iter()
            .map(|device| (HandleKey::for_device(device), Arc::clone(device)))
            .collect();
        *self.nodes.lock().unwrap_or_else(PoisonError::into_inner) = handles;
        Ok(devices)
    }

    /// The cached OS handle for `node`, if it was in the last enumeration.
    fn handle(&self, node: &NodeInfo) -> Result<Arc<Device>, BackendError> {
        self.nodes
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .get(&HandleKey::for_node(node))
            .map(Arc::clone)
            .ok_or(BackendError::Disconnected)
    }

    async fn open_native_raw_writer(
        &self,
        node: &NodeInfo,
    ) -> Result<NativeRawWriter, BackendError> {
        self.device_io.ensure_allowed()?;
        let (_reader, writer) = self
            .handle(node)?
            .open()
            .await
            .map_err(super::backend_error)?;
        self.device_io.ensure_allowed()?;
        Ok(NativeRawWriter {
            writer,
            device_io: self.device_io.clone(),
        })
    }
}

#[async_trait]
impl HidBackend for NativeBackend {
    async fn enumerate(&self) -> Result<Vec<NodeInfo>, BackendError> {
        Ok(self
            .refresh()
            .await?
            .iter()
            .map(|device| super::node_info(device))
            .collect())
    }

    async fn enumerate_hidpp(&self) -> Result<Vec<NodeInfo>, BackendError> {
        Ok(self
            .refresh()
            .await?
            .iter()
            .filter(|device| is_hidpp_node(device))
            .map(|device| super::node_info(device))
            .collect())
    }

    async fn open_hidpp(&self, node: &NodeInfo) -> Result<Option<Arc<HidppChannel>>, BackendError> {
        let Some(recording) = &self.recording else {
            self.device_io.ensure_allowed()?;
            let device = self.handle(node)?;
            return open_hidpp_channel(&device, self.device_io.clone()).await;
        };

    async fn write_report(&self, src: &[u8]) -> Result<usize, Box<dyn Error + Send + Sync>> {
        let mut writer = self.writer.lock().await;
        if let Err(e) = writer.write_output_report(src).await {
            // The native fallback works around async-hid write quirks on a
            // *live* device; reopening a device that is gone can only fail, and
            // its `NativeWriteError` would replace the typed `Disconnected`
            // that `is_permanent_disconnect` needs to retire the channel.
            if matches!(e, async_hid::HidError::Disconnected) {
                return Err(Box::new(e));
            }

            if let Some(native_writer) = &self.native_writer {
                debug!(
                    error = %e,
                    report_id = format_args!("{:#04x}", src.first().copied().unwrap_or_default()),
                    len = src.len(),
                    "async-hid output report write failed; trying native Windows HID fallback"
                );
                native_writer.write_report(src)?;
                return Ok(src.len());
            }

            return Err(Box::new(e));
        }
        Ok(src.len())
    }
}

#[cfg(target_os = "windows")]
pub(super) struct WindowsHidppChannel {
    info: DeviceInfo,
    short: Option<HidEndpoint>,
    long: HidEndpoint,
    /// Cleared the first time either endpoint reports a permanently dead
    /// handle. Read by [`RawHidChannel::is_connected`], which is what lets
    /// `inventory::ledger` evict this channel — the node-vanish path never
    /// fires for a cabled device whose receiver keeps the HID node enumerated.
    connected: AtomicBool,
    device_io: DeviceIoGate,
}

#[cfg(target_os = "windows")]
impl WindowsHidppChannel {
    pub(super) async fn open(
        long_dev: &async_hid::Device,
        long_info: DeviceInfo,
        device_io: DeviceIoGate,
    ) -> Result<Self, async_hid::HidError> {
        let short_dev = find_windows_short_collection(&long_info).await?;
        let (long_reader, long_writer) = long_dev.open().await?;
        let long = HidEndpoint::new(long_reader, long_writer, &long_info);

        let short = match short_dev {
            Some(dev) => {
                let short_info: DeviceInfo = (*dev).clone();
                match dev.open().await {
                    Ok((reader, writer)) => {
                        debug!(
                            name = %short_info.name,
                            pid = format_args!("{:04x}", short_info.product_id),
                            "paired Windows HID++ short collection"
                        );
                        Some(HidEndpoint::new(reader, writer, &short_info))
                    }
                    Err(e) => {
                        debug!(
                            name = %short_info.name,
                            pid = format_args!("{:04x}", short_info.product_id),
                            error = ?e,
                            "could not open Windows HID++ short collection"
                        );
                        None
                    }
                }
            }
            None => None,
        };

        debug!(
            name = %long_info.name,
            pid = format_args!("{:04x}", long_info.product_id),
            supports_short = short.is_some(),
            supports_long = true,
            "opened Windows HID++ composite channel"
        );

        Ok(Self {
            info: long_info,
            short,
            long,
            connected: AtomicBool::new(true),
            device_io,
        })
    }

    result
}

async fn read_report(&self, buf: &mut [u8]) -> Result<usize, Box<dyn Error + Send + Sync>> {
    if let Some(short) = &self.short {
        let mut short_buf = [0u8; SHORT_REPORT_LENGTH];
        let mut long_buf = [0u8; LONG_REPORT_LENGTH];
        let mut short_reader = short.reader.lock().await;
        let mut long_reader = self.long.reader.lock().await;
        // `select!` drops the losing read future, but no report is lost:
        // async-hid's win32 `IoBuffer` owns the in-flight OVERLAPPED read and
        // its buffer (not the future), so the pending operation survives the
        // drop, and the next `read_report` — re-locking this same endpoint —
        // resumes it and retrieves the report. This relies on reusing the
        // per-endpoint reader across calls; do not reopen readers per read.
        return tokio::select! {
            res = short_reader.read_input_report(&mut short_buf) => match res {
                Ok(len) => copy_report(&short_buf, len, buf),
                Err(async_hid::HidError::Disconnected) => self.park_disconnected().await,
                Err(e) => Err(e.into()),
            },
            res = long_reader.read_input_report(&mut long_buf) => match res {
                Ok(len) => copy_report(&long_buf, len, buf),
                Err(async_hid::HidError::Disconnected) => self.park_disconnected().await,
                Err(e) => Err(e.into()),
            },
        };
    }

    let mut reader = self.long.reader.lock().await;
    match reader.read_input_report(buf).await {
        Ok(len) => Ok(len),
        Err(async_hid::HidError::Disconnected) => self.park_disconnected().await,
        Err(e) => Err(e.into()),
    }
}

fn is_connected(&self) -> bool {
    self.connected.load(Ordering::Acquire)
}

fn supports_short_long_hidpp(&self) -> Option<(bool, bool)> {
    Some((self.short.is_some(), true))
}

