//! Implements the `SmartShift` feature (ID `0x2110`) that allows controlling a
//! smart shift enhanced scroll wheel.

use std::hash::Hash;
use std::num::NonZeroU8;

use num_enum::{IntoPrimitive, TryFromPrimitive};
